#!/usr/bin/env python3
"""Generate the offline documentary reader from the Markdown source.
Requires markdown-it-py and beautifulsoup4. No remote assets or product code.
"""
from pathlib import Path
from collections import Counter
from urllib.parse import unquote, urlsplit
import json,re,html
from markdown_it import MarkdownIt
from bs4 import BeautifulSoup
ROOT=Path(__file__).resolve().parents[1]
CSS='\n:root{color-scheme:light;--ink:#18212b;--muted:#536174;--brand:#245bd6;--line:#d9e0e9;--paper:#fff;--canvas:#f7f8fa;--sidebar:300px}\n*{box-sizing:border-box}html{scroll-behavior:auto}body{margin:0;background:var(--canvas);color:var(--ink);font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;font-size:15px;line-height:1.7}a{color:#245bd6;text-underline-offset:3px;overflow-wrap:anywhere}a:hover{color:#1947ad}button,input{font:inherit}button{cursor:pointer;min-height:44px;border:1px solid var(--line);border-radius:8px;background:white;color:var(--ink);padding:8px 13px}button:hover{background:#eef2f7}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #245bd6;outline-offset:3px}.skip{position:absolute;top:-100px;left:15px;background:white;z-index:20;padding:10px}.skip:focus{top:10px}\nheader{position:fixed;inset:0 0 auto 0;height:78px;background:#182a4c;color:#f2f5fa;z-index:10;display:flex;align-items:center;gap:20px;padding:0 26px;box-shadow:0 2px 12px #18212b14}.brand{font-size:25px;letter-spacing:3px;font-weight:750;color:white;text-decoration:none}.edition{border-left:1px solid #71849d;padding-left:20px;line-height:1.4}.edition strong{display:block;font-weight:600;font-size:14px}.edition span{font-size:12px;color:#b0bccc}.header-actions{margin-left:auto;display:flex;gap:8px}.header-actions button{background:transparent;border-color:#71849d;color:white;font-size:13px}.menu-toggle{display:none}\n.sidebar{position:fixed;top:78px;bottom:0;left:0;width:var(--sidebar);background:#ffffff;border-right:1px solid var(--line);overflow:auto;padding:22px 16px 40px;z-index:9}.searchlabel{font-size:12px;color:var(--muted);font-weight:650;display:block;margin-bottom:5px}.searchbox{width:100%;min-height:43px;border:1px solid #78869a;border-radius:8px;padding:8px 10px;background:white}.searchcount{font-size:11px;color:var(--muted);margin:7px 3px 14px;min-height:18px}.navgroup h2{font-size:10px;letter-spacing:1.2px;text-transform:uppercase;color:#536174;margin:25px 10px 9px}.navlink{display:block;font-size:12px;line-height:1.5;padding:9px 11px;border-radius:6px;margin:2px 0;text-decoration:none;color:#536174}.navlink:hover{background:#eef2f7}.navlink[aria-current=page]{background:#eaf0fe;color:#1947ad;font-weight:650;border-left:3px solid #245bd6;padding-left:8px}\nmain{margin-left:var(--sidebar);padding:112px 46px 68px;min-width:0}.document{display:none;max-width:1140px;background:var(--paper);border:1px solid var(--line);border-radius:14px;padding:36px 42px 48px;box-shadow:0 6px 24px #18212b05;min-width:0;margin:0 auto 28px}.document.active,body.all-docs .document{display:block}.docmeta{color:#536174;font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:11px;letter-spacing:.2px;margin-bottom:15px;overflow-wrap:anywhere}h1{font-size:32px;line-height:1.2;letter-spacing:-.8px;margin:0 0 22px;font-weight:740}h2{font-size:22px;line-height:1.35;margin:34px 0 16px;letter-spacing:-.3px}h3{font-size:17px;line-height:1.4;margin:26px 0 10px}h4{font-size:15px}p{margin:13px 0}blockquote{margin:20px 0;padding:8px 17px;border-left:3px solid #78869a;color:#536174;background:#f7f8fa;font-size:13px}blockquote p{margin:4px 0}ul,ol{padding-left:24px}li{margin:6px 0}strong{font-weight:650}hr{border:none;border-top:1px solid var(--line);margin:28px 0}\n.table-scroll{overflow:auto;max-width:100%;border:1px solid var(--line);border-radius:8px;margin:18px 0}table{border-collapse:collapse;width:100%;font-size:12px;line-height:1.65}th{background:#eef2f7;color:#18212b;font-size:11px;text-align:left;font-weight:700;padding:12px;border-bottom:1px solid #d9e0e9;vertical-align:top}td{padding:11px 12px;vertical-align:top;border-bottom:1px solid #d9e0e9;min-width:105px;overflow-wrap:anywhere}tr:last-child td{border-bottom:none}tr:nth-child(even) td{background:#f7f8fa}td:first-child{min-width:65px}code{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:.86em;padding:2px 4px;background:#eef2f7;border-radius:4px;overflow-wrap:anywhere}pre{overflow:auto;max-width:100%;padding:20px;background:#19222e;color:#f2f5fa;border-radius:8px;font-size:12px;line-height:1.6;tab-size:4}pre code{background:none;color:inherit;padding:0;overflow-wrap:normal;white-space:pre;font-size:inherit}a[id],h1[id],h2[id],h3[id]{scroll-margin-top:100px}.reader-note{font-size:11px;text-align:center;color:#536174;margin:18px auto;max-width:900px}.backdrop{display:none}\n@media(max-width:1100px){:root{--sidebar:260px}main{padding:104px 24px 50px}.document{padding:28px}h1{font-size:28px}}\n@media(max-width:850px){:root{--sidebar:290px}.menu-toggle{display:block}.sidebar{transform:translateX(-100%);transition:transform .12s}.nav-open .sidebar{transform:translateX(0)}main{margin-left:0;padding:99px 18px 40px}.nav-open .backdrop{display:block;position:fixed;inset:78px 0 0;background:#18212b55;z-index:8}header{padding:0 17px;gap:14px}.edition{padding-left:14px}.header-actions{gap:5px}.document{padding:26px}.nav-open .sidebar{box-shadow:10px 0 30px #18212b22}}\n@media(max-width:520px){header{height:72px;padding:0 12px;gap:10px}.brand{font-size:19px;letter-spacing:2px}.edition{display:none}.header-actions button{font-size:11px;padding:7px 9px}.header-actions{gap:6px}.sidebar{top:72px}.nav-open .backdrop{top:72px}main{padding:88px 10px 28px}.document{border-radius:10px;padding:22px 17px}h1{font-size:26px}h2{font-size:20px}body{font-size:14px}.docmeta{font-size:10px}td{min-width:135px;padding:9px;font-size:11px}th{padding:9px}pre{font-size:10px;padding:13px}}\n@media(prefers-reduced-motion:reduce){*{transition:none!important}}\n@media print{header,.sidebar,.backdrop,.reader-note{display:none!important}body{background:white;font-size:11px}main{margin:0;padding:0}.document{box-shadow:none;border:0;margin:0;padding:0}.document:not(.active){display:none}body.all-docs .document{display:block;break-before:page}h1{font-size:24px}h2{font-size:18px}pre{white-space:pre-wrap;background:#eef2f7;color:black;font-size:9px}.table-scroll{overflow:visible}table{font-size:9px}th,td{min-width:0;padding:6px}a{color:inherit}}\n\n[hidden]{display:none!important}\n'
SCRIPT_TAIL=" const search=document.getElementById('search'); const count=document.getElementById('searchcount');\nconst menu=document.getElementById('menu'), all=document.getElementById('all');\nfunction closeNav(){document.body.classList.remove('nav-open');menu.setAttribute('aria-expanded','false')}\nfunction route(){let id;try{id=decodeURIComponent(location.hash.slice(1))}catch{ id='doc-readme'};if(id==='main'){document.getElementById('main').focus();return};let target=document.getElementById(id||'doc-readme');let section=target?.closest('.document')||document.getElementById('doc-readme');\n documents.forEach(d=>d.classList.toggle('active',d===section));navlinks.forEach(a=>{if(a.dataset.doc===section.id)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});\n document.title=(searchIndex.find(x=>x.id===section.id)?.title||'Drivy')+' · Drivy V3.17';closeNav();\n if(target&&target!==section){requestAnimationFrame(()=>target.scrollIntoView({block:'start'}))}else requestAnimationFrame(()=>window.scrollTo(0,0));\n}\nwindow.addEventListener('hashchange',route);\nmenu.addEventListener('click',()=>{const open=document.body.classList.toggle('nav-open');menu.setAttribute('aria-expanded',String(open))});\ndocument.getElementById('backdrop').addEventListener('click',closeNav);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNav()});\nall.addEventListener('click',()=>{const active=document.body.classList.toggle('all-docs');all.textContent=active?'Un document':'Tout afficher';all.setAttribute('aria-pressed',String(active));if(!active)route()});\ndocument.getElementById('print').addEventListener('click',()=>window.print());\nsearch.addEventListener('input',()=>{const q=search.value.normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLocaleLowerCase('fr').trim();let n=0;\n navlinks.forEach(a=>{const item=searchIndex.find(x=>x.id===a.dataset.doc);const text=(item.title+' '+item.text).normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLocaleLowerCase('fr');let match=!q||text.includes(q);a.hidden=!match;if(match)n++});\n document.querySelectorAll('.navgroup').forEach(g=>g.hidden=![...g.querySelectorAll('.navlink')].some(x=>!x.hidden));count.textContent=q?n+' document(s) contenant votre recherche':'__DOC_COUNT__ documents · Lecture hors ligne';\n}); route();\n"

CSS += '\n.document img{max-width:100%;height:auto}.document{scroll-margin-top:110px}.document [id]{scroll-margin-top:110px}\n'

def slug(s):
    s=re.sub(r'<[^>]+>','',s.lower().strip())
    s=re.sub(r'[^\w\s-]','',s,flags=re.UNICODE)
    return re.sub(r'\s+','-',s)
def docid(path):return 'doc-'+str(path.with_suffix('')).lower().replace('/','-')
def build():
    files=sorted(ROOT.rglob('*.md'),key=lambda x:('0' if x.name=='COMMENCER_ICI.md' else '1' if x.name=='README.md' else '2')+str(x.relative_to(ROOT)))
    md=MarkdownIt('commonmark',{'html':True}).enable('table')
    groups={'00':'Commencer','DE':'DESIGN · Direction A','01':'01 · Recherche et vision','02':'02 · Expérience','03':'03 · Fonctionnel','04':'04 · Technique','05':'05 · Réalisation','06':'06 · Gouvernance','99':'Historique · non normatif'}
    nav={k:[] for k in groups};sections=[];index=[]
    for f in files:
        rel=f.relative_to(ROOT);ident=docid(rel);text=f.read_text(encoding="utf-8");tokens=md.parse(text);seen=Counter()
        for i,t in enumerate(tokens):
            if t.type=='heading_open':
                base=slug(tokens[i+1].content);n=seen[base];seen[base]+=1;t.attrSet('id',base+(f'-{n}' if n else ''))
        soup=BeautifulSoup(md.renderer.render(tokens,md.options,{}),'html.parser')
        for element in soup.find_all(id=True):element['id']=ident+'--'+element['id']
        for a in soup.find_all('a',href=True):
            link=a['href'];u=urlsplit(link)
            if u.scheme or link.startswith('//'):
                if u.scheme in ('http','https'):a['rel']='noopener noreferrer';a['target']='_blank'
                continue
            target=(f.parent/unquote(u.path)).resolve() if u.path else f.resolve()
            if not target.is_relative_to(ROOT):continue
            dest=target.relative_to(ROOT)
            if dest.suffix=='.md':a['href']='#'+docid(dest)+(('--'+unquote(u.fragment)) if u.fragment else '')
            elif dest.name=='LIRE_DOSSIER.html':a['href']='#doc-readme'
            else:a['href']=dest.as_posix()+('#'+u.fragment if u.fragment else '')
        for image in soup.find_all('img',src=True):
            u=urlsplit(image['src'])
            if not u.scheme and not image['src'].startswith('//'):
                target=(f.parent/unquote(u.path)).resolve()
                if target.is_relative_to(ROOT):image['src']=target.relative_to(ROOT).as_posix()
        for table in soup.find_all('table'):
            wrap=soup.new_tag('div',attrs={'class':'table-scroll','tabindex':'0'});table.wrap(wrap)
            for th in table.find_all('th'):th['scope']='col'
        title=soup.h1.get_text(' ',strip=True) if soup.h1 else f.stem
        historical=(rel.parts[0]=='06-gouvernance' and (f.name.startswith('changements-') or f.name.startswith('audit-corrections-')) and f.name!='audit-corrections-v3-17.md')
        if historical:
            notice=soup.new_tag('blockquote')
            notice.string='Historique : ce document décrit une version antérieure. Pour développer Drivy, utiliser la référence V3.17 et son contrat 3.11.0, pas les décisions abandonnées de ce journal.'
            soup.insert(0,notice)
            title += ' [historique]' 
        group='99' if historical else (rel.parts[0][:2] if len(rel.parts)>1 else '00')
        nav.setdefault(group,[]).append(f'<a class="navlink" data-doc="{ident}" href="#{ident}">{html.escape(title)}</a>')
        index.append({'id':ident,'title':title,'group':group,'text':soup.get_text(' ',strip=True)})
        sections.append(f'<section class="document" id="{ident}" data-path="{rel.as_posix()}" aria-label="{html.escape(title,quote=True)}"><div class="docmeta">{rel.as_posix()}</div>{soup}</section>')
    navbar=''.join(f'<div class="navgroup"><h2>{groups.get(k,k)}</h2>{"".join(items)}</div>' for k,items in nav.items())
    search_json=json.dumps(index,ensure_ascii=False).replace('</',r'<\/')
    script="const documents=[...document.querySelectorAll('.document')],navlinks=[...document.querySelectorAll('.navlink')];const searchIndex="+search_json+';'+SCRIPT_TAIL.replace('__DOC_COUNT__',str(len(files)))
    content='<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Dossier Drivy V3.17 consolidé, documentation et audit."><title>Drivy · Dossier V3.17</title><style>'+CSS+'</style></head><body>'
    content+='<a class="skip" href="#main">Aller au contenu</a><header><a class="brand" href="#doc-readme">DRIVY</a><div class="edition"><strong>Référence de conception · V3.17</strong><span>Swift natif · iPhone / iPad · Web · Android futur</span></div><div class="header-actions"><button class="menu-toggle" id="menu" aria-controls="sidebar" aria-expanded="false">Sommaire</button><button id="all" aria-pressed="false">Tout afficher</button><button id="print">Imprimer</button></div></header><div class="backdrop" id="backdrop"></div>'
    content+='<aside class="sidebar" id="sidebar" aria-label="Documents"><label class="searchlabel" for="search">Rechercher dans le dossier</label><input class="searchbox" id="search" type="search" autocomplete="off" placeholder="Ex. publication, activation, D09"><div class="searchcount" id="searchcount" aria-live="polite">'+str(len(files))+' documents · Lecture hors ligne</div><nav>'+navbar+'</nav></aside>'
    content+='<main id="main" tabindex="-1">'+''.join(sections)+'<p class="reader-note">Documentation de conception corrigée. Aucun écran de l’application n’est implémenté dans ce lecteur.</p></main><noscript><style>.document{display:block!important}</style>JavaScript désactivé : documents affichés à la suite.</noscript><script>'+script+'</script></body></html>'
    (ROOT/'LIRE_DOSSIER.html').write_text(content,encoding='utf-8')
    print(json.dumps({'documents':len(files),'bytes':len(content.encode()),'generated':'LIRE_DOSSIER.html'},ensure_ascii=False))
if __name__=='__main__':build()
